// 383 chars(from 504c) golf by @FabriceNeyret2
void mainImage(out vec4 O, vec2 U) {
    vec2 R = iResolution.xy, s,
         u = 12.*( U+U - R ) / R.y;
    u.y -= 10.5;
    float d=1.;
    for (int c, f, y, i[9], w[9] ; y>=0 ; ) {
        c = int[](2,-1, 3,-1,-1, 3, 1, 2, 1, 1, 2, 2, 1, 3,-1,
                  1, 2,-1, 3, 3,-1,-1, 3,-1, 2, 1, 1, 2, 1, 3
                 )[ w[y]*15 + i[y]++ ];

        c > 1
          ? y == 2 // M
              ?  u -= s = cos( 6.28 * float(f)/6. + vec2(0,11) ),
                 d = min(d, length( u - s * clamp( dot(s, u), -1., 0.)) ), c // line
             : ( i[++y] = 0, w[y] = c-2
               )
          :      f += c;

        while ( i[y] > 14 && --y >= 0 ); 
    }

    O = 1.1 - R.yyyy/36.*d;
}
